CREATE TABLE networks(network_id TEXT PRIMARY KEY CHECK(length(network_id)=32 AND network_id NOT GLOB '*[^0-9a-f]*'),created_at TEXT NOT NULL,initial INTEGER NOT NULL CHECK(initial IN (0,1)));
CREATE UNIQUE INDEX initial_network ON networks(initial) WHERE initial=1;
CREATE TABLE nodes(id TEXT PRIMARY KEY,network_id TEXT NOT NULL REFERENCES networks(network_id),credential_hash BLOB NOT NULL UNIQUE,name TEXT NOT NULL,agent_version TEXT NOT NULL,registered_at TEXT NOT NULL,last_seen TEXT NOT NULL,revoked_at TEXT,mesh_ipv4 TEXT NOT NULL,mesh_ipv6 TEXT NOT NULL,country TEXT,acknowledged_revision INTEGER NOT NULL DEFAULT 0,acknowledged_digest TEXT,UNIQUE(network_id,id),UNIQUE(network_id,mesh_ipv4),UNIQUE(network_id,mesh_ipv6));
CREATE TABLE enrollment_tokens(id TEXT PRIMARY KEY,network_id TEXT NOT NULL REFERENCES networks(network_id),token_hash BLOB NOT NULL UNIQUE,expires_at INTEGER NOT NULL,used_node_id TEXT,binding_hash BLOB,device_binding TEXT,CHECK((used_node_id IS NULL)=(binding_hash IS NULL)),FOREIGN KEY(network_id,used_node_id) REFERENCES nodes(network_id,id));
CREATE TABLE configuration(network_id TEXT NOT NULL REFERENCES networks(network_id),id INTEGER NOT NULL CHECK(id=1),revision INTEGER NOT NULL CHECK(revision BETWEEN 1 AND 4294967295),ipv4_prefix TEXT NOT NULL,ipv6_prefix TEXT NOT NULL,policy TEXT NOT NULL,source_jsonc TEXT,PRIMARY KEY(network_id,id));
CREATE TABLE network_identity(id INTEGER NOT NULL CHECK(id=1),network_id TEXT PRIMARY KEY REFERENCES networks(network_id) CHECK(length(network_id)=32),name TEXT NOT NULL,dns TEXT NOT NULL);
CREATE TABLE connection_identities(node_id TEXT PRIMARY KEY,network_id TEXT NOT NULL REFERENCES networks(network_id),public_key TEXT NOT NULL UNIQUE,capabilities TEXT NOT NULL,FOREIGN KEY(network_id,node_id) REFERENCES nodes(network_id,id));
CREATE TABLE connection_source(network_id TEXT NOT NULL REFERENCES networks(network_id),id INTEGER NOT NULL CHECK(id=1),configuration TEXT NOT NULL,PRIMARY KEY(network_id,id));
CREATE TABLE connection_receipts(node_id TEXT PRIMARY KEY,network_id TEXT NOT NULL REFERENCES networks(network_id),revision INTEGER NOT NULL CHECK(revision BETWEEN 1 AND 4294967295),digest TEXT NOT NULL,saved_at TEXT NOT NULL,FOREIGN KEY(network_id,node_id) REFERENCES nodes(network_id,id));
CREATE TABLE connection_runtime_leases(node_id TEXT PRIMARY KEY,network_id TEXT NOT NULL REFERENCES networks(network_id),instance_id TEXT NOT NULL,epoch INTEGER NOT NULL CHECK(epoch BETWEEN 1 AND 4294967295),UNIQUE(network_id,node_id),FOREIGN KEY(network_id,node_id) REFERENCES nodes(network_id,id));
CREATE TABLE connection_runtime_reports(node_id TEXT PRIMARY KEY,network_id TEXT NOT NULL REFERENCES networks(network_id),sequence INTEGER NOT NULL CHECK(sequence BETWEEN 1 AND 4294967295),body BLOB NOT NULL,reported_at TEXT NOT NULL,FOREIGN KEY(network_id,node_id) REFERENCES connection_runtime_leases(network_id,node_id));
CREATE TABLE mesh_access_source(network_id TEXT NOT NULL REFERENCES networks(network_id),id INTEGER NOT NULL CHECK(id=1),policy TEXT NOT NULL,source_jsonc TEXT,PRIMARY KEY(network_id,id));
CREATE TABLE mesh_access_legacy_v5(network_id TEXT NOT NULL REFERENCES networks(network_id),id INTEGER NOT NULL CHECK(id=1),policy TEXT NOT NULL,PRIMARY KEY(network_id,id));
CREATE TABLE tag_definitions(network_id TEXT NOT NULL REFERENCES networks(network_id),tag TEXT NOT NULL,description TEXT NOT NULL,PRIMARY KEY(network_id,tag));
CREATE TABLE node_tags(network_id TEXT NOT NULL REFERENCES networks(network_id),node_id TEXT NOT NULL,tag TEXT NOT NULL,PRIMARY KEY(network_id,node_id,tag),FOREIGN KEY(network_id,node_id) REFERENCES nodes(network_id,id),FOREIGN KEY(network_id,tag) REFERENCES tag_definitions(network_id,tag));
